// Activate phone + open Ryan partner thread + set Ryan stage to 1 (needed for sidebar visibility)
var v = SugarCube.State.variables;
v.player.flags.phone_active = true;
v.player.flags.ryan_help_tier_open = true;
v.player.flags.ryan_partner_open = true;
v.player.core_traits.npc_ryan_stage = 2;
SugarCube.Engine.show();
JSON.stringify({
  phone_active: v.player.flags.phone_active,
  ryan_help_tier_open: v.player.flags.ryan_help_tier_open,
  ryan_partner_open: v.player.flags.ryan_partner_open,
  npc_ryan_stage: v.player.core_traits.npc_ryan_stage
});

var keys = Object.keys(SugarCube.State.variables);
var d = document.createElement('div'); d.id='__inspect__'; d.style.display='none';
d.textContent = JSON.stringify({
  var_keys: keys,
  player_keys: SugarCube.State.variables.player ? Object.keys(SugarCube.State.variables.player) : null,
  flags_top: SugarCube.State.variables.flags ? Object.keys(SugarCube.State.variables.flags).length : 'no_flags_var'
});
var old = document.getElementById('__inspect__'); if (old) old.remove();
document.body.appendChild(d);

var v = SugarCube.State.variables;
var d = document.createElement('div'); d.id='zzinspect'; d.setAttribute('data-info', JSON.stringify({
  top: Object.keys(v).slice(0,30),
  has_player: !!v.player,
  has_flags: !!v.flags,
  has_phone: !!v.phone,
  player_keys: v.player ? Object.keys(v.player).slice(0,20) : null
}));
document.body.appendChild(d);

var d = document.createElement('div'); d.id='zzurl2';
d.textContent = decodeURIComponent(window.location.href.split('#').pop());
document.body.insertBefore(d, document.body.firstChild);

var el = document.getElementById('zzinspect');
if (el) {
  var d = document.createElement('pre'); d.id='zzdump'; d.style.whiteSpace='pre';
  d.textContent = el.getAttribute('data-info');
  document.body.insertBefore(d, document.body.firstChild);
}

var v = SugarCube.State.variables;
v.flags.phone_active = true;
v.flags.ryan_help_tier_open = true;
v.flags.ryan_partner_open = true;
if (!v.player.core_traits) v.player.core_traits = {};
v.player.core_traits.npc_ryan_stage = 2;
// Also write to npcs.npc_ryan.core_traits if shape is that
if (v.npcs && v.npcs.npc_ryan && v.npcs.npc_ryan.core_traits) {
  v.npcs.npc_ryan.core_traits.npc_ryan_stage = 2;
}
history.replaceState(null,'','#OK:phone=' + v.flags.phone_active + ',ryan_partner_open=' + v.flags.ryan_partner_open + ',stage=' + v.player.core_traits.npc_ryan_stage);
SugarCube.Engine.show();

var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') {
    links[i].click();
    history.replaceState(null,'','#PhoneClicked');
    break;
  }
}

// Look for any open dialog/popup
var els = document.querySelectorAll('[role=dialog], #ui-dialog, .modal, .dialog, .phone-modal');
var info = [];
for (var i=0;i<els.length;i++) {
  var e = els[i];
  info.push({tag: e.tagName, id: e.id, cls: e.className, vis: e.offsetParent !== null, txt: (e.innerText||'').slice(0,300)});
}
history.replaceState(null,'','#DLG:' + encodeURIComponent(JSON.stringify(info)));

var p = document.createElement('pre'); p.id='zzdump2'; p.style.whiteSpace='pre-wrap';
p.textContent = decodeURIComponent(window.location.hash);
document.body.insertBefore(p, document.body.firstChild);

var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') {
    links[i].scrollIntoView();
    // SugarCube click handlers usually attach via jQuery; trigger via dispatchEvent
    var evt = new MouseEvent('click', {bubbles:true, cancelable:true, view:window});
    links[i].dispatchEvent(evt);
    break;
  }
}

var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') {
    var el = links[i];
    history.replaceState(null,'','#PHONE_LINK:tag=' + el.tagName + ',href=' + (el.getAttribute('href')||'NONE') + ',data-passage=' + (el.getAttribute('data-passage')||'NONE') + ',onclick=' + (el.getAttribute('onclick')?'YES':'NO') + ',cls=' + el.className);
    break;
  }
}

var p = document.createElement('pre'); p.id='zzph'; 
p.textContent = decodeURIComponent(window.location.hash);
// Insert at top of ui-bar so it survives ui re-render
var bar = document.getElementById('ui-bar-body') || document.body;
bar.insertBefore(p, bar.firstChild);

var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') {
    var el = links[i];
    var info = 'PHONE_DEBUG:tag=' + el.tagName + 
      ' href=' + (el.getAttribute('href')||'NONE') + 
      ' data-passage=' + (el.getAttribute('data-passage')||'NONE') + 
      ' onclick=' + (el.onclick?'YES':'NO') +
      ' parent_cls=' + (el.parentElement?el.parentElement.className:'') +
      ' outerHTML_excerpt=' + el.outerHTML.slice(0,200);
    // Set on the toggle button title attribute (UI element that won't be wiped)
    var t = document.getElementById('ui-bar-toggle') || document.querySelector('[title="Toggle the UI bar"]');
    if (t) t.setAttribute('title', info);
    break;
  }
}

var t = document.querySelector('[title]');
// find the one with PHONE_DEBUG
var all = document.querySelectorAll('[title]');
for (var i=0;i<all.length;i++) {
  if ((all[i].getAttribute('title')||'').startsWith('PHONE_DEBUG')) {
    var p = document.createElement('span'); p.id='zzphd'; p.textContent = all[i].getAttribute('title');
    document.body.insertBefore(p, document.body.firstChild);
    break;
  }
}

var links = document.querySelectorAll('a');
var phoneLink = null;
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') { phoneLink = links[i]; break; }
}
if (phoneLink) {
  // Try multiple ways
  phoneLink.scrollIntoView({block:'center'});
  var before = document.body.innerHTML.length;
  phoneLink.click();
  var after_click = document.body.innerHTML.length;
  // wait briefly via synchronous busy loop won't work; just check dialog
  var d = document.getElementById('ui-dialog');
  var hasD = d && d.style.display !== 'none' && d.offsetParent !== null;
  history.replaceState(null,'', '#CLICK_RESULT:before=' + before + ',after=' + after_click + ',dialog=' + hasD);
}

var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') {
    links[i].scrollIntoView({block:'center'});
    links[i].click();
    break;
  }
}

// Reopen phone
var links = document.querySelectorAll('a');
for (var i=0; i<links.length; i++) {
  if (links[i].textContent.trim() === '📱 Phone') { links[i].click(); break; }
}

// Click Messages
var btns = document.querySelectorAll('#ui-dialog button, #ui-dialog a, #ui-dialog [class*=phone-app]');
for (var i=0; i<btns.length; i++) {
  if (btns[i].textContent.indexOf('Messages') !== -1) { btns[i].click(); break; }
}

// Click Ryan inside the dialog only
var dlg = document.getElementById('ui-dialog');
if (dlg) {
  var els = dlg.querySelectorAll('*');
  for (var i=0; i<els.length; i++) {
    if (els[i].textContent && els[i].textContent.trim().indexOf('Ryan') === 0 && els[i].children.length < 5) {
      // click the parent clickable
      var t = els[i];
      while (t && !t.onclick && t.tagName !== 'BUTTON' && t.tagName !== 'A' && !t.classList.contains('clickable')) {
        t = t.parentElement;
        if (t === dlg) { t = null; break; }
      }
      if (t) { t.click(); break; }
    }
  }
}

